const icon=(name)=>`<svg class="icon ${name}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.box}</svg>`;
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='invento-v3', clone=x=>JSON.parse(JSON.stringify(x));
